					case 3:
						septFactorL = PrevFL - inputSampleL;
						septCL += septFactorL; septBL -= septFactorL;
						septFactorL = septCL * aw_f_septIntensity;
						
						septFactorR = PrevFR - inputSampleR;
						septCR += septFactorR; septBR -= septFactorR;
